import * as THREE from 'three';

import { attachShaderClippedSection } from '../../utils/ThreeMaterialUtils';

import { Asset } from './';

export class Materials {
	public asset: Asset;

	public normalMap: THREE.Texture;

	public skinMaterial: THREE.MeshPhysicalMaterial | THREE.MeshStandardMaterial;
	public skeletonMaterial: THREE.MeshPhysicalMaterial | THREE.MeshStandardMaterial;

	public glassMaterial: THREE.MeshPhysicalMaterial;

	public clippingPlanes = [];

	public valueYClipping = 30;
	public valueXClipping = 30;
	public valueZClipping = 30;

	constructor(asset: Asset) {
		this.asset = asset;
	}
	public async init() {
		const globalClippingPlaneA = this.clippingPlanes.push(
			new THREE.Plane(new THREE.Vector3(0, -1, 0), this.valueYClipping),
			new THREE.Plane(new THREE.Vector3(-1, 0, 0), this.valueXClipping),
			new THREE.Plane(new THREE.Vector3(0, 0, -1), this.valueZClipping)
		);

		const textureLoader = new THREE.TextureLoader();
		// const normalMapPath = process.env.PUBLIC_URL + '/static/data/model/map/normal-1.jpg';
		let normalMapPath = 'https://raw.githubusercontent.com/NamjuLee/data/master/map/';

		if (this.asset.appCore.isPerformanceMode) {
			normalMapPath += 'normal-1-small.jpg';
		} else {
			normalMapPath += 'normal-1.jpg';
		}

		const clippingProperties = {
			clippingPlanes: this.clippingPlanes,
			transparent: false,
			opacity: 1.0,
			side: THREE.DoubleSide,
			depthWrite: true,
		};

		this.normalMap = textureLoader.load(normalMapPath, (texture) => {
			texture.wrapS = THREE.RepeatWrapping;
			texture.wrapT = THREE.RepeatWrapping;
			texture.repeat.set(10, 10);
		});

		if (this.asset.appCore.rendererCore.useWebGPU) {
			this.normalMap = null;
		}

		if (this.asset.appCore.rendererCore.useWebGPU || this.asset.appCore.isPerformanceMode) {
			this.skinMaterial = new THREE.MeshStandardMaterial({
				color: new THREE.Color(0x828282),
				roughness: 0.2,
				metalness: 0.1,
				normalMap: this.asset.appCore.isPerformanceMode ? null : this.normalMap,
				normalScale: new THREE.Vector2(0.1, 0.1),

				...clippingProperties,
			});

			this.skeletonMaterial = new THREE.MeshStandardMaterial({
				color: new THREE.Color(0xb6b6b6),
				roughness: 0.1,
				metalness: 0.2,
				normalMap: this.asset.appCore.isPerformanceMode ? null : this.normalMap,
				normalScale: new THREE.Vector2(0.1, 0.1),

				...clippingProperties,
			});
		} else {
			this.skinMaterial = new THREE.MeshPhysicalMaterial({
				color: new THREE.Color(0x828282), // 0xa2a2a2
				roughness: 0.2,
				metalness: 0.1,
				clearcoat: 0.3,
				clearcoatRoughness: 0.5,
				normalMap: this.normalMap,
				normalScale: new THREE.Vector2(0.1, 0.1),

				...clippingProperties,
			});

			this.skeletonMaterial = new THREE.MeshPhysicalMaterial({
				color: new THREE.Color(0xb6b6b6), // 0xe1e1e1
				roughness: 0.1,
				metalness: 0.2,
				clearcoat: 1.0,
				clearcoatRoughness: 0.05,
				normalMap: this.normalMap,
				normalScale: new THREE.Vector2(0.25, 0.25),

				...clippingProperties,
			});
		}

		this.skeletonMaterial.onBeforeCompile = (shader: THREE.Shader) => {
			shader.uniforms.clippedSectionColor = { value: new THREE.Vector3(0, 0, 0) };
			shader.fragmentShader =
				`
				uniform vec3 clippedSectionColor;
				` + shader.fragmentShader;

			shader.fragmentShader = shader.fragmentShader.replace(
				'#include <opaque_fragment>',
				`
				if (gl_FrontFacing == false) {
					outgoingLight = clippedSectionColor; // Set clipped section to black
				}
				#include <opaque_fragment>
				`
			);

			// console.log('Modified Fragment Shader:', shader.fragmentShader);
		};

		this.glassMaterial = new THREE.MeshPhysicalMaterial({
			transparent: true,
			side: THREE.DoubleSide,
			depthWrite: false,
			color: '#000000',
			metalness: 0,
			roughness: 0.05,
			transmission: 0.8,
			thickness: 2.5,
			ior: 1.45,
			reflectivity: 0.8,

			opacity: 0.45,
			envMap: this.asset.appCore.rendererCore.hdriWrapper ? this.asset.appCore.rendererCore.hdriWrapper.envMap : null,
			clearcoat: 1.0,
			clearcoatRoughness: 0.1,
			envMapIntensity: 0.8,
			clippingPlanes: this.clippingPlanes,
		});

		attachShaderClippedSection(this.skinMaterial);
	}
	public updateYClipping(value: number) {
		this.clippingPlanes[0].constant = value;
	}
	public updateXClipping(value: number) {
		this.clippingPlanes[1].constant = value;
	}
	public updateZClipping(value: number) {
		this.clippingPlanes[2].constant = value;
	}
}
